```rust
// Re-implementing relational storage and nested-loop joins manually in application memory
struct Row {
    id: u64,
    data: HashMap<String, String>,
}

struct MemoryDatabase {
    tables: HashMap<String, Vec<Row>>,
}

impl MemoryDatabase {
    fn manual_join(&self, left_table: &str, right_table: &str, join_col: &str) -> Vec<Row> {
        let mut results = Vec::new();
        if let (Some(left), Some(right)) = (self.tables.get(left_table), self.tables.get(right_table)) {
            for l_row in left {
                for r_row in right {
                    // Manual, slow, un-indexed quadratic nested-loop join
                    if l_row.data.get(join_col) == r_row.data.get(join_col) {
                        results.push(l_row.clone());
                    }
                }
            }
        }
        results
    }
}
```

fix:
When the data belongs to a database, push relational filtering, index traversal, and joins into indexed database queries. For genuinely in-memory data, use a suitable indexed lookup (e.g. a `HashMap` keyed by ID) rather than nested scans, and do not introduce a database solely to eliminate a loop.

```rust
// Delegation of data queries and joins to the underlying database engine
let posts_with_authors = sqlx::query!(
    "SELECT p.*, a.name FROM posts p JOIN authors a ON p.author_id = a.id"
)
.fetch_all(&mut pool)
.await?;
```
